const b = $input.first().json.body ?? {};
const errors = [];
if (!b.order_id) errors.push('order_id is required');
if (!Array.isArray(b.items) || b.items.length === 0) errors.push('items[] is required');
else b.items.forEach((it, i) => {
  if (!it.product_id) errors.push(`items[${i}].product_id missing`);
  if (!(Number(it.quantity) > 0)) errors.push(`items[${i}].quantity must be > 0`);
});
const priority = String(b.priority || 'NORMAL').toUpperCase();
if (!['LOW', 'NORMAL', 'HIGH', 'URGENT'].includes(priority)) errors.push('priority must be LOW|NORMAL|HIGH|URGENT');
if (b.deadline && isNaN(Date.parse(b.deadline))) errors.push('deadline must be an ISO-8601 date');
return [{ json: { valid: errors.length === 0, errors, order: { ...b, priority } } }];

// ======================= EDIT ME =======================
const CONFIG = { api_base: 'http://host.docker.internal:8000', default_mode: 'agentic' };
// =======================================================
// Every experiment mode = previous mode + one extra capability (see WH-05).
const MODES = {
  "random": {
    "assignment": "random",
    "path_algo": "dijkstra",
    "use_predictions": false,
    "use_replanning": false,
    "use_vision": false,
    "use_agents": false,
    "use_rl": false
  },
  "heuristic": {
    "assignment": "nearest",
    "path_algo": "dijkstra",
    "use_predictions": false,
    "use_replanning": false,
    "use_vision": false,
    "use_agents": false,
    "use_rl": false
  },
  "astar": {
    "assignment": "nearest",
    "path_algo": "astar",
    "use_predictions": false,
    "use_replanning": false,
    "use_vision": false,
    "use_agents": false,
    "use_rl": false
  },
  "ml": {
    "assignment": "ml_eta",
    "path_algo": "astar",
    "use_predictions": true,
    "use_replanning": false,
    "use_vision": false,
    "use_agents": false,
    "use_rl": false
  },
  "dynamic": {
    "assignment": "ml_eta",
    "path_algo": "astar",
    "use_predictions": true,
    "use_replanning": true,
    "use_vision": true,
    "use_agents": false,
    "use_rl": false
  },
  "agentic": {
    "assignment": "ml_eta",
    "path_algo": "astar",
    "use_predictions": true,
    "use_replanning": true,
    "use_vision": true,
    "use_agents": true,
    "use_rl": false
  },
  "rl": {
    "assignment": "ml_eta",
    "path_algo": "astar",
    "use_predictions": true,
    "use_replanning": true,
    "use_vision": true,
    "use_agents": true,
    "use_rl": true
  }
};
const j = $input.first().json;
let trigger = { type: 'schedule' }, mode = CONFIG.default_mode, meta = {};
if (j.order) {
  trigger = { type: 'new_order', new_order: j.order };
} else if (j.body) {
  const b = j.body;
  trigger = { type: 'experiment_cycle' };
  mode = b.mode || mode;
  meta = { experiment_id: b.experiment_id ?? null, cycle: b.cycle ?? null, seed: b.seed ?? null };
}
if (!MODES[mode]) throw new Error(`Unknown mode "${mode}". Valid: ${Object.keys(MODES).join(', ')}`);
return [{ json: {
  run_id: `run_${$execution.id}`, api_base: CONFIG.api_base, mode, features: MODES[mode],
  trigger, meta, started_at: new Date().toISOString(),
} }];

// Optional stage guard: if the stage failed or returned nothing, keep the previous
// context and mark the stage as degraded instead of stopping the whole cycle.
const prev = $('08 A* / Dijkstra Path Planning').first().json;
const res = $input.first().json;
if (!res || res.error || !res.context) {
  const reason = (res && res.error && (res.error.message || res.error)) || 'rl service unavailable';
  return [{ json: { ...prev, context: { ...prev.context, rl: { status: 'degraded', reason: String(reason) } } } }];
}
return [{ json: res }];

const j = $input.first().json;
const n = (j.context && j.context.replan_attempts) || 0;
if (n > 5) throw new Error(`Replanning did not converge after ${n} attempts (${j.run_id || 'run'})`);
return [{ json: j }];

// Optional stage guard: if the stage failed or returned nothing, keep the previous
// context and mark the stage as degraded instead of stopping the whole cycle.
const prev = $('11 SimPy Simulation Step').first().json;
const res = $input.first().json;
if (!res || res.error || !res.context) {
  const reason = (res && res.error && (res.error.message || res.error)) || 'vision service unavailable';
  return [{ json: { ...prev, context: { ...prev.context, vision: { status: 'degraded', reason: String(reason) } } } }];
}
return [{ json: res }];

const rc = $('Build Run Context').first().json;
const ev = $('15 Evaluation Engine').first().json.context || {};
return [{ json: {
  status: 'completed', run_id: rc.run_id, mode: rc.mode, trigger: rc.trigger.type, meta: rc.meta,
  metrics: ev.evaluation || {}, safety: ev.safety || {},
  degraded: { rl: (ev.rl || {}).status === 'degraded', vision: (ev.vision || {}).status === 'degraded' },
  duration_ms: Date.now() - Date.parse(rc.started_at),
} }];
